"""CARLA-lazy source-gated taxi and passenger construction.

Native acquisition must supply independently reviewed original site bytes.
This component owns its actors and cameras; frame capture is a separate step.
"""

from __future__ import annotations

import hashlib
import json
import math
import queue
import copy
from pathlib import Path

from taxi_stand_measurement import VIEWS, finite, polygon, within

SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "curb_reference": (1280, 720), "passenger_side": (1280, 720)}


def pose(value: dict) -> dict:
    if not isinstance(value, dict):
        raise ValueError("reviewed Native transform required")
    for name in ("x", "y", "z", "yaw"):
        finite(value.get(name), "transform " + name)
    for name in ("pitch", "roll"):
        finite(value.get(name, 0), "transform " + name)
    return value


def read_site(path: Path, sha256: str) -> dict:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != sha256:
        raise ValueError("reviewed original taxi site SHA256 differs")
    site = json.loads(raw)
    if site.get("source_kind") != "original_independent_site_review":
        raise ValueError("original independent taxi site review required")
    if site.get("cell_id") != "C378245" or site.get("business_district") is not True:
        raise ValueError("reviewed taxi cell/district differs")
    if not site.get("map_sha256") or not site.get("designation_id"):
        raise ValueError("reviewed map and stand designation required")
    stand = polygon(site.get("stand_polygon_xy_m"), "stand")
    street = polygon(site.get("street_polygon_xy_m"), "street")
    scene = site.get("native_scene")
    if not isinstance(scene, dict):
        raise ValueError("reviewed Native taxi scene required")
    if not str(scene.get("taxi_blueprint_id", "")).startswith("vehicle."):
        raise ValueError("reviewed taxi vehicle blueprint required")
    if not str(scene.get("passenger_blueprint_id", "")).startswith("walker.pedestrian."):
        raise ValueError("reviewed passenger blueprint required")
    transforms = scene.get("halt_poses")
    if not isinstance(transforms, dict) or set(transforms) != {"in_stand", "outside_stand"}:
        raise ValueError("reviewed in/out stand poses required")
    for location, transform in transforms.items():
        pose(transform)
        xy = (transform["x"], transform["y"])
        if not within(xy, street):
            raise ValueError("reviewed halt pose outside street")
        if within(xy, stand) != (location == "in_stand"):
            raise ValueError("reviewed halt pose differs from stand boundary")
    for name in ("passenger_start_pose", "passenger_door_pose"):
        pose(scene.get(name))
    cameras = scene.get("camera_mounts")
    if not isinstance(cameras, dict) or set(cameras) != set(VIEWS):
        raise ValueError("four reviewed taxi camera mounts required")
    for name, value in cameras.items():
        if value.get("attach_to") not in ("taxi", "world"):
            raise ValueError("reviewed taxi camera parent required")
        pose(value.get("transform"))
        fov = finite(value.get("fov_deg"), name + " camera fov")
        if not 0 < fov < 180:
            raise ValueError("reviewed taxi camera fov invalid")
    return site


class NativeTaxiOperator:
    def __init__(self, world, carla, site: dict):
        self.world, self.carla, self.site = world, carla, site
        self.owned = []
        self.taxi = self.passenger = None
        self.cameras = {}

    def transform(self, value: dict):
        p = pose(value)
        return self.carla.Transform(
            self.carla.Location(x=p["x"], y=p["y"], z=p["z"]),
            self.carla.Rotation(yaw=p["yaw"], pitch=p.get("pitch", 0), roll=p.get("roll", 0)))

    def spawn(self, blueprint_id: str, transform: dict, **kwargs):
        blueprint = self.world.get_blueprint_library().find(blueprint_id)
        actor = self.world.spawn_actor(blueprint, self.transform(transform), **kwargs)
        if actor is None:
            raise ValueError("Native taxi actor spawn failed: " + blueprint_id)
        self.owned.append(actor)
        return actor

    def setup(self, case: dict) -> dict:
        location = case.get("location_request")
        activity = case.get("halt_activity_request")
        exchange = case.get("passenger_exchange_request")
        if location not in ("in_stand", "outside_stand") or activity not in ("park", "stand", "temporary_stop"):
            raise ValueError("unselected taxi location/activity request")
        if exchange not in ("none", "loading", "unloading"):
            raise ValueError("unselected taxi passenger request")
        if activity != "temporary_stop" and exchange != "none":
            raise ValueError("taxi halt/activity pairing differs")
        if activity == "temporary_stop" and exchange == "none" and not case["case_id"].endswith("__outside_stand_idle_stop"):
            raise ValueError("taxi halt/activity pairing differs")
        raw_map = self.world.get_map().to_opendrive().encode("utf-8")
        if hashlib.sha256(raw_map).hexdigest() != self.site["map_sha256"]:
            raise ValueError("reviewed taxi OpenDRIVE differs from Native world")
        scene = self.site["native_scene"]
        try:
            self.taxi = self.spawn(scene["taxi_blueprint_id"], scene["halt_poses"][location])
            if exchange != "none":
                self.passenger = self.spawn(scene["passenger_blueprint_id"],
                                            scene["passenger_start_pose"])
            for view in VIEWS:
                spec = scene["camera_mounts"][view]
                blueprint = self.world.get_blueprint_library().find("sensor.camera.rgb")
                width, height = SIZES[view]
                blueprint.set_attribute("image_size_x", str(width))
                blueprint.set_attribute("image_size_y", str(height))
                blueprint.set_attribute("fov", str(spec["fov_deg"]))
                kwargs = {"attach_to": self.taxi} if spec["attach_to"] == "taxi" else {}
                sensor = self.world.spawn_actor(blueprint, self.transform(spec["transform"]), **kwargs)
                if sensor is None:
                    raise ValueError("Native taxi camera spawn failed: " + view)
                self.owned.append(sensor)
                self.cameras[view] = sensor
            loc = self.taxi.get_transform().location
            center = (finite(loc.x, "taxi readback x"), finite(loc.y, "taxi readback y"))
            if within(center, polygon(self.site["stand_polygon_xy_m"], "stand")) != (location == "in_stand"):
                raise ValueError("Native taxi halt location differs from reviewed stand")
            return {"taxi_actor_id": self.taxi.id,
                    "passenger_actor_id": self.passenger.id if self.passenger else None,
                    "camera_actor_ids": {name: actor.id for name, actor in self.cameras.items()},
                    "reviewed_location": location, "requested_activity": activity,
                    "requested_exchange": exchange}
        except BaseException:
            self.close()
            raise

    def close(self):
        errors = []
        for actor in reversed(self.owned):
            try:
                if hasattr(actor, "stop"):
                    actor.stop()
                actor.destroy()
            except BaseException as error:
                errors.append(error)
        self.owned.clear()
        self.cameras.clear()
        self.taxi = self.passenger = None
        if errors:
            raise ValueError("Native taxi ownership cleanup failed") from errors[0]

    def capture(self, output: Path, *, frames: int = 900) -> dict:
        """Save all four Native camera streams and taxi kinematics by world tick.

        This records construction behavior only. It does not assert a passenger
        boarded, that a halt was expeditious, or that parking rules were met.
        """
        if self.taxi is None or set(self.cameras) != set(VIEWS):
            raise ValueError("taxi and four cameras must be constructed")
        if frames != 900:
            raise ValueError("exact 45-second 20-Hz capture required")
        output = Path(output)
        if output.exists():
            raise ValueError("retain prior Native taxi attempt")
        output.mkdir(parents=True)
        previous_settings = copy.deepcopy(self.world.get_settings())
        capture_settings = copy.deepcopy(previous_settings)
        capture_settings.synchronous_mode = True
        capture_settings.fixed_delta_seconds = 0.05
        self.world.apply_settings(capture_settings)
        inboxes = {name: queue.Queue() for name in VIEWS}
        ledger = []
        try:
            for name, sensor in self.cameras.items():
                sensor.listen(lambda image, target=inboxes[name]: target.put(image))
            for index in range(frames):
                native_frame = self.world.tick()
                frame_images = {}
                for name in VIEWS:
                    image = inboxes[name].get(timeout=30)
                    if image.frame != native_frame:
                        raise ValueError("Native taxi camera/world frame mismatch")
                    target = output / name
                    target.mkdir(exist_ok=True)
                    image_path = target / (f"{index:04d}.png")
                    image.save_to_disk(str(image_path))
                    frame_images[name] = {"path": str(image_path.relative_to(output)),
                                          "sha256": hashlib.sha256(image_path.read_bytes()).hexdigest(),
                                          "native_frame": native_frame}
                transform = self.taxi.get_transform()
                location = transform.location
                velocity = self.taxi.get_velocity()
                box = self.taxi.bounding_box
                corners = []
                for dx, dy in ((-1, -1), (1, -1), (1, 1), (-1, 1)):
                    local = self.carla.Location(x=dx * box.extent.x, y=dy * box.extent.y,
                                                z=0)
                    vertex = transform.transform(box.location + local)
                    corners.append([finite(vertex.x, "body x"), finite(vertex.y, "body y")])
                ledger.append({"frame": index, "native_frame": native_frame,
                               "elapsed_s": index / 20,
                               "taxi_center_xy_m": [finite(location.x, "taxi x"),
                                                    finite(location.y, "taxi y")],
                               "taxi_footprint_xy_m": corners,
                               "taxi_speed_mps": math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2),
                               "cameras": frame_images})
            (output / "native_frames.json").write_text(json.dumps(ledger, indent=2) + "\n")
            return {"frame_count": frames, "rate_hz": 20, "camera_views": list(VIEWS),
                    "native_frames_sha256": hashlib.sha256(
                        (output / "native_frames.json").read_bytes()).hexdigest(),
                    "physical_observation_verified": False}
        finally:
            for sensor in self.cameras.values():
                sensor.stop()
            self.world.apply_settings(previous_settings)

"""Saved-source measurements for a taxi stand and passenger exchange.

The procedure reports observed geometry and activity. Whether a stop is
expeditious or complies with other regulations remains a separate review.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT = "testing__C378245__LVMC-11-60-040__taxi_driver"
VIEWS = ("overview", "approach", "curb_reference", "passenger_side")


def raw_source(root: Path, ref: dict) -> bytes:
    if not isinstance(ref, dict) or not isinstance(ref.get("path"), str):
        raise ValueError("source path and digest required")
    path = Path(ref["path"])
    if path.is_absolute() or ".." in path.parts:
        raise ValueError("source must stay beneath source root")
    raw = (root / path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != ref.get("sha256"):
        raise ValueError("source SHA256 differs")
    return raw


def record(root: Path, ref: dict) -> dict:
    return json.loads(raw_source(root, ref))


def finite(value, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("finite original " + name + " required")
    return float(value)


def polygon(value, name: str) -> list[tuple[float, float]]:
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError("reviewed " + name + " polygon required")
    points = []
    for point in value:
        if not isinstance(point, list) or len(point) != 2:
            raise ValueError("reviewed " + name + " vertex required")
        points.append((finite(point[0], name + " x"), finite(point[1], name + " y")))
    return points


def within(point: tuple[float, float], shape: list[tuple[float, float]]) -> bool:
    x, y = point
    inside = False
    for i, (ax, ay) in enumerate(shape):
        bx, by = shape[(i + 1) % len(shape)]
        if (ay > y) != (by > y):
            crossing = ax + (y - ay) * (bx - ax) / (by - ay)
            if x < crossing:
                inside = not inside
    return inside


def measure(packet: dict, root: Path) -> dict:
    if (packet.get("assignment_id"), packet.get("cell_id"), packet.get("actor")) != (ASSIGNMENT, "C378245", "taxi_driver"):
        raise ValueError("taxi assignment identity differs")
    if packet.get("law_id") != "LVMC-11-60-040":
        raise ValueError("taxi law identity differs")
    case = packet.get("case_id")
    if not isinstance(case, str) or not case.startswith(ASSIGNMENT + "__"):
        raise ValueError("exact case identity required")
    site = record(root, packet.get("reviewed_site"))
    native = record(root, packet.get("native_result"))
    frames = record(root, packet.get("native_frames"))
    activity = record(root, packet.get("activity_review"))
    documents = {name: record(root, packet.get(name)) for name in
                 ("stand_designation", "taxi_licence", "other_regulations")}
    cameras = packet.get("camera_sources")
    if not isinstance(cameras, dict) or set(cameras) != set(VIEWS):
        raise ValueError("four original camera source references required")
    camera_hashes = {name: hashlib.sha256(raw_source(root, cameras[name])).hexdigest()
                     for name in VIEWS}
    if site.get("source_kind") != "original_independent_site_review":
        raise ValueError("original independent stand site review required")
    if site.get("cell_id") != "C378245" or site.get("business_district") is not True:
        raise ValueError("reviewed business-district cell differs")
    if site.get("street_public_access") is not True or not site.get("jurisdiction_review_id"):
        raise ValueError("street and jurisdiction review required")
    if site.get("map_sha256") != native.get("map_sha256"):
        raise ValueError("reviewed site differs from Native map")
    stand = polygon(site.get("stand_polygon_xy_m"), "stand")
    street = polygon(site.get("street_polygon_xy_m"), "street")
    if documents["stand_designation"].get("designation_id") != site.get("designation_id"):
        raise ValueError("taxi-stand designation differs")
    if documents["stand_designation"].get("authority_reviewed") is not True:
        raise ValueError("official stand designation review required")
    if documents["taxi_licence"].get("vehicle_id") != native.get("taxi_vehicle_id"):
        raise ValueError("licensed taxicab identity differs")
    if documents["taxi_licence"].get("operator_id") != native.get("operator_id"):
        raise ValueError("operator identity differs")
    if documents["other_regulations"].get("review_id") != site.get("other_regulation_review_id"):
        raise ValueError("other stop/parking regulation review differs")
    if native.get("source_kind") != "original_native" or native.get("case_id") != case:
        raise ValueError("original exact-case Native result required")
    if native.get("frame_count") != 900 or not isinstance(frames, list) or len(frames) != 900:
        raise ValueError("complete 900-frame Native history required")
    if native.get("recording_id") != packet.get("recording_id"):
        raise ValueError("original recording identity differs")
    if activity.get("source_kind") != "original_independent_activity_review":
        raise ValueError("independent passenger activity review required")
    if activity.get("recording_id") != packet["recording_id"] or activity.get("case_id") != case:
        raise ValueError("activity review identity differs")
    if activity.get("camera_sha256") != camera_hashes:
        raise ValueError("passenger review camera bytes differ")
    interval = activity.get("halt_interval_frames")
    if not isinstance(interval, list) or len(interval) != 2 or any(type(x) is not int for x in interval):
        raise ValueError("reviewed halt interval required")
    first, last = interval
    if not 0 <= first < last < 900:
        raise ValueError("reviewed halt interval outside capture")
    if activity.get("activity") not in ("park", "stand", "temporary_stop"):
        raise ValueError("reviewed activity type required")
    if not activity.get("reviewer_id"):
        raise ValueError("independent activity reviewer required")
    positions = []
    footprints = []
    speeds = []
    for i, row in enumerate(frames):
        if row.get("frame") != i or finite(row.get("elapsed_s"), "time") != i / 20:
            raise ValueError("original Native frame/time gap")
        xy = row.get("taxi_center_xy_m")
        if not isinstance(xy, list) or len(xy) != 2:
            raise ValueError("original taxi center missing")
        positions.append((finite(xy[0], "taxi x"), finite(xy[1], "taxi y")))
        body = row.get("taxi_footprint_xy_m")
        if not isinstance(body, list) or len(body) != 4:
            raise ValueError("four original taxi footprint corners required")
        corners = []
        for corner in body:
            if not isinstance(corner, list) or len(corner) != 2:
                raise ValueError("original taxi footprint corner missing")
            corners.append((finite(corner[0], "taxi body x"),
                            finite(corner[1], "taxi body y")))
        footprints.append(corners)
        speeds.append(finite(row.get("taxi_speed_mps"), "taxi speed"))
    halt_positions = positions[first:last + 1]
    halt_footprints = footprints[first:last + 1]
    halt_speeds = speeds[first:last + 1]
    if not all(within(xy, street) for corners in halt_footprints for xy in corners):
        raise ValueError("taxi halt lies outside reviewed street polygon")
    # 0.1 m/s is only an engineering stationarity tolerance, not legal duration.
    if max(halt_speeds) > 0.1:
        raise ValueError("reviewed halt interval includes moving taxi")
    events = activity.get("passenger_events")
    if not isinstance(events, list):
        raise ValueError("original passenger event review required")
    for event in events:
        if (event.get("kind") not in ("boarding", "alighting") or
            type(event.get("frame")) is not int or not first <= event["frame"] <= last or
            not event.get("passenger_actor_id") or event.get("observed") is not True):
            raise ValueError("passenger event lacks original review")
    return {
        "format": "worker-taxi-stand-measurement",
        "case_id": case,
        "recording_id": packet["recording_id"],
        "reviewed_activity": activity["activity"],
        "halt_interval_frames": interval,
        "max_halt_speed_mps": max(halt_speeds),
        "all_halt_centers_inside_designated_stand": all(within(xy, stand) for xy in halt_positions),
        "all_halt_centers_outside_designated_stand": all(not within(xy, stand) for xy in halt_positions),
        "all_halt_footprints_inside_designated_stand": all(
            within(xy, stand) for corners in halt_footprints for xy in corners),
        "all_halt_footprints_outside_designated_stand": all(
            not within(xy, stand) for corners in halt_footprints for xy in corners),
        "passenger_event_kinds": [event["kind"] for event in events],
        "source_sha256": {name: packet[name]["sha256"] for name in
                          ("reviewed_site", "native_result", "native_frames", "activity_review",
                           "stand_designation", "taxi_licence", "other_regulations")},
        "camera_sha256": camera_hashes,
        "expeditiousness": "requires_independent_review",
        "other_regulation_compliance": "requires_independent_review",
        "legal_verdict": None,
    }

"""Fake Native world checks actor setup, map binding and cleanup."""

from __future__ import annotations

import hashlib
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

REPO = Path(__file__).resolve().parents[3]
ROOT = Path(__file__).resolve().parents[1]
import sys
sys.path.insert(0, str(ROOT))
from native_taxi_operator import NativeTaxiOperator, read_site

SCRATCH = REPO / ".runtime-work/c378245-native-tests"
SCRATCH.mkdir(parents=True, exist_ok=True)


def site():
    pose = lambda x, y: {"x": x, "y": y, "z": 0.5, "yaw": 0}
    return {
        "source_kind": "original_independent_site_review", "cell_id": "C378245",
        "business_district": True, "map_sha256": hashlib.sha256(b"map-fixture").hexdigest(),
        "designation_id": "stand-fixture",
        "stand_polygon_xy_m": [[0, 0], [5, 0], [5, 4], [0, 4]],
        "street_polygon_xy_m": [[-10, -10], [20, -10], [20, 10], [-10, 10]],
        "native_scene": {
            "taxi_blueprint_id": "vehicle.fixture.taxi",
            "passenger_blueprint_id": "walker.pedestrian.fixture",
            "halt_poses": {"in_stand": pose(2, 2), "outside_stand": pose(8, 2)},
            "passenger_start_pose": pose(9, 3), "passenger_door_pose": pose(8, 2),
            "camera_mounts": {name: {"attach_to": "taxi", "transform": pose(0, 0), "fov_deg": 90}
                              for name in ("overview", "approach", "curb_reference", "passenger_side")},
        },
    }


class Blueprint:
    def __init__(self, name):
        self.name, self.attributes = name, {}

    def set_attribute(self, name, value):
        self.attributes[name] = value


class Blueprints:
    def find(self, name):
        return Blueprint(name)


class Actor:
    def __init__(self, identity, blueprint, transform):
        self.id, self.blueprint, self.transform = identity, blueprint, transform
        self.destroyed = False
        self.callback = None
        self.bounding_box = type("Box", (), {
            "extent": type("Extent", (), {"x": 0.4, "y": 0.4})(),
            "location": Carla.Location(x=0, y=0, z=0)})()

    def get_transform(self):
        return self.transform

    def destroy(self):
        self.destroyed = True

    def stop(self):
        pass

    def listen(self, callback):
        self.callback = callback

    def get_velocity(self):
        return Carla.Location(x=0, y=0, z=0)


class Map:
    def to_opendrive(self):
        return "map-fixture"


class World:
    def __init__(self, fail_on=None):
        self.actors, self.fail_on = [], fail_on
        self.frame = 0
        self.settings = type("Settings", (), {"synchronous_mode": False,
                                              "fixed_delta_seconds": None})()

    def get_map(self):
        return Map()

    def get_blueprint_library(self):
        return Blueprints()

    def spawn_actor(self, blueprint, transform, **kwargs):
        if blueprint.name == self.fail_on:
            return None
        actor = Actor(len(self.actors) + 1, blueprint, transform)
        self.actors.append(actor)
        return actor

    def get_settings(self):
        return self.settings

    def apply_settings(self, settings):
        self.settings = settings

    def tick(self):
        self.frame += 1
        for actor in self.actors:
            if actor.callback:
                actor.callback(type("Image", (), {"frame": self.frame,
                    "save_to_disk": lambda _, path: Path(path).write_bytes(b"fixture image")})())
        return self.frame


class Carla:
    class Location:
        def __init__(self, **kwargs):
            self.__dict__.update(kwargs)

        def __add__(self, other):
            return Carla.Location(x=self.x + other.x, y=self.y + other.y, z=self.z + other.z)

    class Rotation:
        def __init__(self, **kwargs):
            self.__dict__.update(kwargs)

    class Transform:
        def __init__(self, location, rotation):
            self.location, self.rotation = location, rotation

        def transform(self, offset):
            return self.location + offset


class NativeTaxiTests(unittest.TestCase):
    def test_site_source_hash_and_geometry(self):
        with tempfile.TemporaryDirectory(dir=SCRATCH) as name:
            path = Path(name) / "reviewed-site.json"
            raw = json.dumps(site()).encode()
            path.write_bytes(raw)
            self.assertEqual(read_site(path, hashlib.sha256(raw).hexdigest())["designation_id"], "stand-fixture")
            with self.assertRaisesRegex(ValueError, "SHA256"):
                read_site(path, "0" * 64)

    def test_builds_stand_taxi_and_four_cameras_then_releases(self):
        world = World()
        operator = NativeTaxiOperator(world, Carla, site())
        result = operator.setup({"case_id": "fixture__designated_stand_park", "location_request": "in_stand",
                                 "halt_activity_request": "park", "passenger_exchange_request": "none"})
        self.assertEqual(len(result["camera_actor_ids"]), 4)
        self.assertIsNone(result["passenger_actor_id"])
        self.assertEqual(world.actors[1].blueprint.attributes["image_size_x"], "1920")
        operator.close()
        self.assertTrue(all(actor.destroyed for actor in world.actors))

    def test_loading_spawns_passenger_at_outside_stand(self):
        world = World()
        operator = NativeTaxiOperator(world, Carla, site())
        result = operator.setup({"case_id": "fixture__outside_stand_load", "location_request": "outside_stand",
                                 "halt_activity_request": "temporary_stop", "passenger_exchange_request": "loading"})
        self.assertIsNotNone(result["passenger_actor_id"])
        self.assertEqual(result["reviewed_location"], "outside_stand")
        operator.close()

    def test_camera_failure_releases_owned_taxi(self):
        world = World(fail_on="sensor.camera.rgb")
        operator = NativeTaxiOperator(world, Carla, site())
        with self.assertRaisesRegex(ValueError, "camera spawn"):
            operator.setup({"case_id": "fixture__designated_stand_park", "location_request": "in_stand",
                            "halt_activity_request": "park", "passenger_exchange_request": "none"})
        self.assertTrue(all(actor.destroyed for actor in world.actors))

    def test_native_map_mismatch_rejected_before_spawn(self):
        original = site()
        original["map_sha256"] = "0" * 64
